head.script:
scwin.onpageload = function () {

window.clickCnt = 0;

var tmpJSON = [
		{ "col1": "1", "col2": "2", "col3": "3", "col4": "4", "col5": "5", "col6": "6" },
		{ "col1": "2", "col2": "2", "col3": "3", "col4": "4", "col5": "5", "col6": "6" },
		{ "col1": "3", "col2": "2", "col3": "3", "col4": "4", "col5": "5", "col6": "6" }
	];
	dataList1.setJSON(tmpJSON);
};

scwin.onpageunload = function () {

};
scwin.gridView1_onheaderclick = function(){
	console.log("scwin.gridView1_onheaderclick");
	window.clickCnt++;
}

	scwin.checkVal = function() {
		return window.clickCnt == 1;
	}
	scwin.unitTest = function() {
		//Init test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column6').children[1].click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run and Stop unit Test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
